# Records run_in_terminal and appmod-* tool calls as JSONL for the extension to process.

$raw = [Console]::In.ReadToEnd()

if ($raw -notmatch '"tool_name"\s*:\s*"([^"]+)"') { exit 0 }
$toolName = $Matches[1]

if ($toolName -ne 'run_in_terminal' -and $toolName -notlike 'appmod-*') { exit 0 }

if ($raw -notmatch '"session_id"\s*:\s*"([^"]+)"') { exit 0 }
$sessionId = $Matches[1]

$hooksDir = '.github\modernize\java-upgrade\hooks'
if (-not (Test-Path $hooksDir)) { New-Item -ItemType Directory -Path $hooksDir -Force | Out-Null }

$line = ($raw -replace '[\r\n]+', ' ').Trim() + "`n"
[System.IO.File]::AppendAllText("$hooksDir\$sessionId.json", $line, [System.Text.UTF8Encoding]::new($false))

package pe.edu.utp.huellitas.config;

import org.springframework.web.servlet.HandlerInterceptor;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;

public class AuthInterceptor implements HandlerInterceptor {

    @Override
    public boolean preHandle(
            HttpServletRequest request,
            HttpServletResponse response,
            Object handler) throws Exception {

        HttpSession session = request.getSession(false);

        if (session != null &&
            session.getAttribute("usuario") != null) {

            return true;
        }

        response.sendRedirect("/login");
        return false;
    }
}

package pe.edu.utp.huellitas.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

@Configuration
public class WebConfig implements WebMvcConfigurer {

    @Override
    public void addInterceptors(InterceptorRegistry registry) {

        registry.addInterceptor(new AuthInterceptor())
                .addPathPatterns("/**")
                .excludePathPatterns(
                        "/",
                        "/login",
                        "/css/**",
                        "/js/**",
                        "/images/**"
                        //si ponemos registro, nos hackean nmms
                );
    }
}

package pe.edu.utp.huellitas.controller;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

import jakarta.servlet.http.HttpSession;
import pe.edu.utp.huellitas.model.Personal;
import pe.edu.utp.huellitas.service.LoginService;

@Controller
public class LoginController {

    private final LoginService loginService;

    public LoginController(LoginService loginService) {
        this.loginService = loginService;
    }

    @GetMapping("/")
    public String inicio() {
        return "redirect:/login";
    }

    @GetMapping("/login")
    public String login() {
        return "login";
    
    }
    
    @PostMapping("/login")
    public String validarLogin(
            @RequestParam String username,
            @RequestParam String password,
            HttpSession session,
            Model model) {

        Personal usuario =
                loginService.autenticar(username, password);

        if(usuario == null) {

            model.addAttribute(
                    "error",
                    "Usuario o contraseña incorrectos");

            return "login";
        }

        session.setAttribute("usuario", usuario);

        return "redirect:/dashboard";
    }

    @GetMapping("/logout")
    public String logout(HttpSession session) {

        session.invalidate();

        return "redirect:/";
    }
}

package pe.edu.utp.huellitas.controller;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.RequestParam;
import jakarta.validation.Valid;

import pe.edu.utp.huellitas.model.Paciente;
import pe.edu.utp.huellitas.model.Propietario;
import pe.edu.utp.huellitas.service.PacienteService;
import pe.edu.utp.huellitas.service.PropietarioService;

@Controller
@RequestMapping("/pacientes")
public class PacienteController {

    private final PacienteService pacienteService;
    private final PropietarioService propietarioService;

    public PacienteController(PacienteService pacienteService, PropietarioService propietarioService) {
        this.pacienteService = pacienteService;
        this.propietarioService = propietarioService;
    }

    @GetMapping
    public String listar(@RequestParam(required = false) String buscar, Model model) {
        model.addAttribute("pacientes", pacienteService.listarTodos(buscar));
        model.addAttribute("buscar", buscar);
        return "pacientes/listar";
    }

    @GetMapping("/nuevo")
    public String nuevo(Model model) {
        Paciente paciente = new Paciente();
        paciente.setPropietario(new Propietario());

        cargarFormulario(model, paciente, "Registrar paciente");
        return "pacientes/form";
    }

    @PostMapping("/guardar")
    public String guardar(@Valid @ModelAttribute Paciente paciente, BindingResult result, Model model) {
        if (result.hasErrors()) {
            if (paciente.getPropietario() == null) {
                paciente.setPropietario(new Propietario());
            }
            cargarFormulario(
                    model,
                    paciente,
                    paciente.getId() == null ? "Registrar paciente" : "Editar paciente"
            );
            return "pacientes/form";
        }

        try {
            pacienteService.guardar(paciente);
            return "redirect:/pacientes";
        } catch (IllegalArgumentException e) {
            if (paciente.getPropietario() == null) {
                paciente.setPropietario(new Propietario());
            }

            cargarFormulario(
                    model,
                    paciente,
                    paciente.getId() == null ? "Registrar paciente" : "Editar paciente"
            );

            model.addAttribute("error", e.getMessage());
            return "pacientes/form";
        }
    }

    @GetMapping("/editar/{id}")
    public String editar(@PathVariable Long id, Model model) {
        Paciente paciente = pacienteService.obtenerPorId(id);
        cargarFormulario(model, paciente, "Editar paciente");
        return "pacientes/form";
    }

    @GetMapping("/eliminar/{id}")
    public String eliminar(@PathVariable Long id) {
        pacienteService.eliminar(id);
        return "redirect:/pacientes";
    }

    private void cargarFormulario(Model model, Paciente paciente, String titulo) {
        model.addAttribute("paciente", paciente);
        model.addAttribute("propietarios", propietarioService.listarTodos());
        model.addAttribute("titulo", titulo);
    }
}

package pe.edu.utp.huellitas.controller;

import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;

import jakarta.validation.Valid;
import pe.edu.utp.huellitas.model.Personal;
import pe.edu.utp.huellitas.service.PersonalService;

@Controller
@RequestMapping("/personal")
public class PersonalController {

    private final PersonalService service;

    public PersonalController(PersonalService service) {
        this.service = service;
    }

    @GetMapping
    public String listarPersonal(Model model) {
        model.addAttribute("listaPersonal", service.listarTodos());
        model.addAttribute("nuevoPersonal", new Personal());
        return "personal";
    }

    @PostMapping("/guardar")
    public String guardarPersonal(
        @Valid @ModelAttribute("nuevoPersonal") Personal personal,
        BindingResult result,
        Model model) {

    if (result.hasErrors()) {
        model.addAttribute("listaPersonal", service.listarTodos());
        return "personal";
    }

    String error = service.guardar(personal);

    if (error != null) {
        model.addAttribute("errorCodigo", error);
        model.addAttribute("listaPersonal", service.listarTodos());
        return "personal";
    }

    return "redirect:/personal";
}
}

