    background-color: rgba(36, 229, 210, 0.1); /* Tono Accent transparente */
    color: var(--primary);
    border-left-color: var(--accent);
    font-weight: 600;
}
.sidebar .nav-link i { width: 24px; margin-right: 12px; color: #9ca3af; }
.sidebar .nav-link.active i { color: var(--primary); }

main { margin-left: 260px; padding: 30px; }

/* la UI */
/* Tarjetas */
.card {
    background-color: #ffffff;
    border: 1px solid var(--border-color) !important;
    border-radius: 12px;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03) !important;
    transition: none;
}
.card-header {
    background-color: transparent !important;
    border-bottom: 1px solid var(--border-color);
    padding: 1.5rem 1.5rem 0.5rem;
}

/* Botones */
.btn {
    border-radius: 6px;
    font-weight: 500;
    padding: 0.5rem 1.25rem;
    letter-spacing: 0.3px;
    border: none;
}
.btn-primary { background-color: var(--primary) !important; color: white !important; }
.btn-primary:hover { background-color: #1e6c8a !important; transform: translateY(-1px); }
.btn-success { background-color: #10b981 !important; color: white !important;}
.btn-danger { background-color: var(--danger) !important; color: white !important; }
.btn-warning { background-color: var(--warning) !important; color: #000 !important; }

/* Formularios */
.form-control, .form-select {
    border-radius: 6px;
    border: 1px solid var(--border-color);
    padding: 0.6rem 1rem;
    color: var(--text-main);
    font-size: 0.95rem;
    box-shadow: none;
}
.form-control:focus, .form-select:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(37, 132, 167, 0.1);
}
label.form-label, .text-muted.small.d-block {
    font-weight: 500;
    color: var(--text-muted);
    margin-bottom: 0.4rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.error-message { color: var(--danger); font-size: 0.875rem; margin-top: 0.25rem; }
h2.fw-bold { color: var(--primary); letter-spacing: -0.5px; }

/* Tablas */
.table { vertical-align: middle; }
.table thead th {
    border-bottom: 2px solid var(--border-color);
    color: var(--text-muted);
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    padding: 1rem;
    background-color: transparent !important;
}
.table tbody td {
    padding: 1rem;
    border-bottom: 1px solid var(--border-color);
    color: var(--text-main);
}

/*responsive */
@media (max-width: 767.98px) {
    .sidebar {
        position: static; width: 100%; height: auto;
        padding-top: 0; border-right: none; border-bottom: 1px solid var(--border-color);
    }
    main { margin-left: 0 !important; padding: 15px; }
    body { padding-top: 56px; }
}
